const itens = $input.all().map((i) => i.json);
const hojeLabel = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

const BADGE_FAIXA = { 5: '🥉', 7: '🥈', 8: '🥇', 10: '🏆' };
const MEDALHA_POSICAO = ['🥇', '🥈', '🥉'];

function fmtBRL(v) {
  return (Number(v) || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
}

function marca(v) {
  return v ? '✅' : '❌';
}

const linhas = [`📊 *Performance do dia — ${hojeLabel}*`, ''];

itens.forEach((v, idx) => {
  const posicao = MEDALHA_POSICAO[idx] ?? '▪️';
  const faixa = v.faixa_semana != null ? Number(v.faixa_semana) : 3;
  const badge = BADGE_FAIXA[faixa] ? ` ${BADGE_FAIXA[faixa]}` : '';
  linhas.push(`${posicao} *${v.nome_vendedor}*${badge}`);
  linhas.push(`💰 Hoje: ${fmtBRL(v.margem_dia)} (${v.percentual_dia ?? 0}% da meta do dia)`);
  linhas.push(`📅 Semana: ${fmtBRL(v.margem_semana)} (${v.percentual_semana ?? 0}% da meta) — faixa ${faixa}%`);
  linhas.push(`🧾 ${v.qtd_notas_dia} venda(s) — ${v.vendas_cliente_real} com cliente, ${v.vendas_proprio_cpf} no CPF do vendedor, ${v.vendas_sem_cliente} sem cliente`);
  linhas.push(`📦 Lançou falta: ${marca(v.lancou_falta)} · 📞 Fez contato: ${marca(v.fez_contato)}`);
  linhas.push('');
});

return [{ json: { mensagem: linhas.join('\n').trim() } }];
